import { css, cx } from '@emotion/css';
import * as React from 'react';
import { useState } from 'react';
import { useToggle } from 'react-use';

import { type GrafanaTheme2, type DataTransformerConfig } from '@grafana/data';
import { t } from '@grafana/i18n';
import { FieldValidationMessage, Icon, Input, useStyles2 } from '@grafana/ui';

import { validateTransformationRefId } from './transformationRefId';

export interface Props {
  index: number;
  transformation: DataTransformerConfig;
  transformations: DataTransformerConfig[];
  transformationTypeName: string;
  disabled?: boolean;
  onChange: (index: number, config: DataTransformerConfig) => void;
  /** Whether this transformation produces a frame of its own whose name can be pinned. */
  canSetRefId?: boolean;
  /** The name the output frame gets when none is pinned. Undefined when there is no single output. */
  dynamicRefId?: string;
  /** refIds already in the input. Reusing one would make a downstream byRefId filter select both frames. */
  reservedRefIds?: string[];
}

export const TransformationOperationRowHeader = (props: Props) => {
  const {
    index,
    transformation,
    transformations,
    onChange,
    disabled,
    transformationTypeName,
    canSetRefId = false,
    dynamicRefId,
    reservedRefIds = [],
  } = props;

  const styles = useStyles2(getStyles);
  const [isRefIdEditing, toggleIsRefIdEditing] = useToggle(false);
  const [isStaticRefId, setIsStaticRefId] = useState(transformation.refId !== undefined);
  const [validationError, setValidationError] = useState<string | null>(null);

  const isRefIdEditable = canSetRefId;

  const validateRefId = (refId: string): string | null =>
    validateTransformationRefId(refId, { transformation, transformations, reservedRefIds });

  const onEndEditRefId = (newRefId: string) => {
    const trimmedNewRefId = newRefId.trim();
    toggleIsRefIdEditing(false);
    setValidationError(null);

    if (validateRefId(trimmedNewRefId) !== null) {
      return;
    }

    if (transformation.refId !== trimmedNewRefId && trimmedNewRefId !== '') {
      setIsStaticRefId(true);
      onChange(index, {
        ...transformation,
        refId: trimmedNewRefId,
      });
    } else if (trimmedNewRefId === '') {
      // if it was previously custom and is now empty, it is being cleared out and we want to save it as undefined
      if (isStaticRefId) {
        onChange(index, {
          ...transformation,
          refId: undefined,
        });
      }
      // either way, if it is empty, we want it to display as not static
      setIsStaticRefId(false);
    }
  };

  const onInputChange = (event: React.SyntheticEvent<HTMLInputElement>) => {
    setValidationError(validateRefId(event.currentTarget.value.trim()));
  };

  const onEditRefIdBlur = (event: React.SyntheticEvent<HTMLInputElement>) => {
    onEndEditRefId(event.currentTarget.value.trim());
  };

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      onEndEditRefId(event.currentTarget.value);
    }
  };

  const onFocus = (event: React.FocusEvent<HTMLInputElement>) => {
    event.target.select();
  };

  return (
    <div className={styles.wrapper}>
      {isRefIdEditable && !isRefIdEditing && (
        <button
          className={styles.refIdWrapper}
          title={t(
            'dashboard.transformation-operation-row.transformation-editor-row-header.edit-refId',
            'Edit transformation name'
          )}
          onClick={() => toggleIsRefIdEditing()}
          data-testid="transformation-refid-div"
          type="button"
        >
          <span className={cx(styles.refIdStyle, !isStaticRefId && styles.placeholderText)}>
            {transformation.refId ||
              dynamicRefId ||
              t(
                'dashboard.transformation-operation-row.transformation-editor-row-header.edit-refId-placeholder',
                '(Auto)'
              )}
          </span>
          <Icon name="pen" className={styles.refIdEditIcon} size="sm" />
        </button>
      )}

      {isRefIdEditable && isRefIdEditing && (
        <>
          <Input
            type="text"
            defaultValue={transformation.refId}
            onBlur={onEditRefIdBlur}
            autoFocus
            onKeyDown={onKeyDown}
            onFocus={onFocus}
            invalid={validationError !== null}
            onChange={onInputChange}
            className={styles.refIdInput}
            data-testid="transformation-refid-input"
          />
          {validationError && <FieldValidationMessage horizontal>{validationError}</FieldValidationMessage>}
        </>
      )}
      <div>
        <div className={cx(styles.title, disabled && styles.disabled)}>{transformationTypeName}</div>
      </div>
    </div>
  );
};

const getStyles = (theme: GrafanaTheme2) => {
  return {
    wrapper: css({
      label: 'Wrapper',
      display: 'flex',
      alignItems: 'center',
      overflow: 'hidden',
    }),
    refIdWrapper: css({
      display: 'flex',
      cursor: 'pointer',
      border: '1px solid transparent',
      borderRadius: theme.shape.radius.default,
      alignItems: 'center',
      margin: 0,
      background: 'transparent',
      overflow: 'hidden',

      '&:hover': {
        background: theme.colors.action.hover,
        border: `1px dashed ${theme.colors.border.strong}`,
      },

      '&:focus': {
        border: `2px solid ${theme.colors.primary.border}`,
      },

      '&:hover, &:focus': {
        '.transformation-refid-edit-icon': {
          visibility: 'visible',
        },
      },
    }),
    refIdStyle: css({
      fontWeight: theme.typography.fontWeightMedium,
      color: theme.colors.primary.text,
      cursor: 'pointer',
      overflow: 'hidden',
    }),
    refIdEditIcon: cx(
      css({
        marginLeft: theme.spacing(1),
        visibility: 'hidden',
      }),
      'transformation-refid-edit-icon'
    ),
    refIdInput: css({
      maxWidth: '300px',
      margin: '-4px 0',
    }),
    placeholderText: css({
      fontWeight: theme.typography.fontWeightRegular,
      fontSize: theme.typography.bodySmall.fontSize,
      color: theme.colors.text.secondary,
      alignItems: 'center',
      fontStyle: 'italic',
      textOverflow: 'ellipsis',
    }),
    title: css({
      fontWeight: theme.typography.fontWeightBold,
      color: theme.colors.text.link,
      marginLeft: theme.spacing(0.5),
      overflow: 'hidden',
      textOverflow: 'ellipsis',
    }),
    disabled: css({
      color: theme.colors.text.disabled,
    }),
  };
};
